1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Linear initiative — multi-agent collaboration for correctness</title>
7	<style>
8	  :root {
9	    --bg: #fcfcfd;
10	    --surface: #ffffff;
11	    --fg: #0a0a0f;
12	    --fg-soft: #2e2e38;
13	    --muted: #5f5f6a;
14	    --rule: #e3e3ea;
15	    --rule-soft: #f1f1f5;
16	    --accent: #4a3bef;       --accent-soft: #efedff;
17	    --ok:     #047a44;       --ok-soft:     #e6f5ed;
18	    --info:   #1957c4;       --info-soft:   #e7f0fd;
19	    --warn:   #8b4a05;       --warn-soft:   #fbf0e0;
20	    --danger: #a82a3f;       --danger-soft: #fbe6ea;
21	  }
22	  @media (prefers-color-scheme: dark) {
23	    :root {
24	      --bg: #0b0b10; --surface: #15151c;
25	      --fg: #f4f4f7;
26	      --fg-soft: #d6d6dd;
27	      --muted: #9d9dab;
28	      --rule: #2a2a35; --rule-soft: #1c1c24;
29	      --accent: #a99dff;       --accent-soft: #2a2548;
30	      --ok:     #6fd4a0;       --ok-soft:     #122922;
31	      --info:   #8eb8ff;       --info-soft:   #14233b;
32	      --warn:   #f0a35a;       --warn-soft:   #2a1f12;
33	      --danger: #f08597;       --danger-soft: #29151b;
34	    }
35	  }
36	  * { box-sizing: border-box; }
37	  html, body { margin: 0; padding: 0; background: var(--bg); color: var(--fg); }
38	  body {
39	    font: 16px/1.65 "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
40	    font-feature-settings: "cv11", "ss01", "ss03", "kern", "liga";
41	    -webkit-font-smoothing: antialiased;
42	    -moz-osx-font-smoothing: grayscale;
43	  }
44	  a { color: var(--accent); text-decoration: none; }
45	  a:hover { text-decoration: underline; }
46	  code, pre { font-family: ui-monospace, SFMono-Regular, "JetBrains Mono", Menlo, monospace; }
47	
48	  /* ---------- Layout ---------- */
49	  .layout { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; max-width: 1200px; margin: 0 auto; }
50	
51	  /* ---------- Sidebar ---------- */
52	  aside {
53	    position: sticky; top: 0; align-self: start; height: 100vh; overflow-y: auto;
54	    padding: 28px 22px; border-right: 1px solid var(--rule); background: var(--bg);
55	  }
56	  aside .brand { display: flex; align-items: center; gap: 8px; font-weight: 600; font-size: 14px; margin-bottom: 28px; color: var(--fg); }
57	  aside .brand .dot { width: 18px; height: 18px; border-radius: 5px; background: linear-gradient(135deg, var(--accent), #8c7bff); flex-shrink: 0; }
58	  aside .kicker { font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); margin: 24px 0 10px; font-weight: 700; }
59	  aside .kicker:first-of-type { margin-top: 0; }
60	  aside nav ol { list-style: none; padding: 0; margin: 0; counter-reset: nav; }
61	  aside nav li { counter-increment: nav; margin: 2px 0; }
62	  aside nav li.h3 { margin-left: 28px; counter-increment: none; }
63	  aside nav a {
64	    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 6px;
65	    color: var(--fg-soft); font-size: 14.5px; transition: background 0.12s, color 0.12s;
66	  }
67	  aside nav li:not(.h3) > a::before { content: counter(nav, decimal-leading-zero); font: 600 12px/1 ui-monospace, monospace; color: var(--muted); width: 20px; flex-shrink: 0; }
68	  aside nav a:hover { background: var(--rule-soft); color: var(--fg); text-decoration: none; }
69	  aside nav a.active { background: var(--accent-soft); color: var(--accent); }
70	  aside nav a.active::before { color: var(--accent); }
71	  aside .status-block { font-size: 13.5px; color: var(--fg-soft); line-height: 1.55; }
72	
73	  /* ---------- Main ---------- */
74	  main { padding: 40px 56px 80px; max-width: 860px; }
75	
76	  /* ---------- Document header ---------- */
77	  .doc-head { margin-bottom: 32px; }
78	  .breadcrumbs { font-size: 13.5px; color: var(--muted); margin-bottom: 16px; }
79	  .breadcrumbs span { color: var(--fg-soft); }
80	  main h1 { font-size: 34px; line-height: 1.2; margin: 0 0 12px; letter-spacing: -0.02em; font-weight: 700; color: var(--fg); }
81	  .doc-subtitle { font-size: 17px; color: var(--fg-soft); margin: 0 0 18px; line-height: 1.45; font-weight: 500; max-width: 60ch; }
82	  .pill-row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 0; }
83	  .pill-row:empty { display: none; }
84	
85	  /* ---------- Pills ---------- */
86	  .pill {
87	    display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; border-radius: 999px;
88	    font: 600 13px/1 "Inter", ui-sans-serif, system-ui, sans-serif; letter-spacing: 0.01em; white-space: nowrap;
89	  }
90	  .pill .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
91	  .pill-meta     { background: var(--rule-soft); color: var(--fg-soft); font-weight: 500; }
92	  .pill-accepted, .pill-ok        { background: var(--ok-soft);     color: var(--ok); }
93	  .pill-proposed, .pill-draft     { background: var(--info-soft);   color: var(--info); }
94	  .pill-rejected, .pill-deprecated{ background: var(--danger-soft); color: var(--danger); }
95	  .pill-superseded, .pill-flagged { background: var(--warn-soft);   color: var(--warn); }
96	
97	  /* ---------- Metadata grid ---------- */
98	  .meta-grid {
99	    display: grid; grid-template-columns: max-content 1fr; gap: 8px 22px;
100	    background: var(--surface); border: 1px solid var(--rule); border-radius: 10px;
101	    padding: 16px 20px; margin: 22px 0 0; font-size: 14px;
102	  }
103	  .meta-grid dt { color: var(--muted); font-weight: 600; }
104	  .meta-grid dd { margin: 0; color: var(--fg); font-family: ui-monospace, SFMono-Regular, monospace; font-size: 13.5px; word-break: break-word; }
105	
106	  /* ---------- Section header ---------- */
107	  section.s { margin: 56px 0; scroll-margin-top: 20px; }
108	  section.s > header { display: flex; align-items: baseline; gap: 12px; margin-bottom: 18px; flex-wrap: wrap; }
109	  section.s .ix { font: 700 12px/1 ui-monospace, monospace; color: var(--muted); padding: 4px 8px; border: 1px solid var(--rule); border-radius: 4px; flex-shrink: 0; }
110	  main h2 { font-size: 22px; line-height: 1.3; margin: 0; letter-spacing: -0.01em; font-weight: 700; color: var(--fg); }
111	  main h3 { font-size: 17px; line-height: 1.4; margin: 28px 0 10px; font-weight: 650; color: var(--fg); scroll-margin-top: 20px; }
112	
113	  /* ---------- Prose defaults ---------- */
114	  main p { margin: 0 0 16px; color: var(--fg-soft); }
115	  main ul, main ol { margin: 0 0 16px; padding-left: 26px; color: var(--fg-soft); }
116	  main li { margin: 6px 0; }
117	  main pre { background: var(--rule-soft); padding: 16px 18px; border-radius: 8px; overflow-x: auto; font-size: 14px; line-height: 1.6; border: 1px solid var(--rule); }
118	  main code { font-size: 0.92em; padding: 2px 6px; background: var(--rule-soft); border-radius: 4px; color: var(--fg); }
119	  main pre code { padding: 0; background: transparent; font-size: 1em; }
120	  main blockquote { margin: 18px 0; padding: 10px 18px; border-left: 4px solid var(--accent); color: var(--fg-soft); background: var(--accent-soft); border-radius: 0 6px 6px 0; }
